const crypto = require('crypto');
const event = $json.body ?? {};
const headers = $json.headers ?? {};
const secret = $env.ASK_N8N_WEBHOOK_SECRET ?? '';
if (!secret) throw new Error('ASK_N8N_WEBHOOK_SECRET is not configured');
const stable = (value) => {
  if (Array.isArray(value)) return '[' + value.map(stable).join(',') + ']';
  if (value && typeof value === 'object') return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stable(value[key])).join(',') + '}';
  return JSON.stringify(value);
};
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(stable(event)).digest('hex');
const supplied = String(headers['x-ask-signature'] ?? '');
const valid = supplied.length === expected.length && crypto.timingSafeEqual(Buffer.from(supplied), Buffer.from(expected));
if (!valid) throw new Error('Invalid operational-event signature');
const latency = Number(event.elapsed_ms ?? 0);
const attention = ['error', 'timeout'].includes(event.outcome) || event.guard_ok === false || latency >= 10000;
const severity = ['error', 'timeout'].includes(event.outcome) ? 'critical' : attention ? 'warning' : 'info';
return [{ json: { ...event, requires_attention: attention, severity } }];
